// deepCloneObject is called when deepClone receives a plain object
import { deepClone } from 'src/options/clone.js'

describe('deepCloneObject', () => {
  test('should create a deep copy of a plain object', () => {
    const original = {
      a: 1,
      b: 'test',
      c: { nested: 'value' },
      d: [1, 2, 3]
    }

    const copy = deepClone(original)

    // Should be deeply equal
    expect(copy).toEqual(original)

    // Should not be the same reference
    expect(copy).not.toBe(original)
    expect(copy.c).not.toBe(original.c)
    expect(copy.d).not.toBe(original.d)

    // Modifying the copy should not affect original
    copy.a = 2
    copy.c.nested = 'modified'
    copy.d.push(4)

    expect(original.a).toBe(1)
    expect(original.c.nested).toBe('value')
    expect(original.d).toEqual([1, 2, 3])
  })

  test('should handle empty objects', () => {
    const original = {}
    const copy = deepClone(original)

    expect(copy).toEqual({})
    expect(copy).not.toBe(original)
  })

  test('should preserve property descriptors', () => {
    const original = {}

    // Add a property with specific descriptor
    Object.defineProperty(original, 'readonly', {
      value: 'cannot change',
      writable: false,
      enumerable: true,
      configurable: true
    })

    Object.defineProperty(original, 'hidden', {
      value: 'hidden value',
      enumerable: false,
      configurable: true
    })

    const copy = deepClone(original)

    // Check property exists
    expect(copy.readonly).toBe('cannot change')
    expect(copy.hidden).toBe('hidden value')

    // Check descriptors
    const readonlyDesc = Object.getOwnPropertyDescriptor(copy, 'readonly')
    expect(readonlyDesc.writable).toBe(false)
    expect(readonlyDesc.enumerable).toBe(true)

    const hiddenDesc = Object.getOwnPropertyDescriptor(copy, 'hidden')
    expect(hiddenDesc.enumerable).toBe(false)
  })

  test('should handle symbols as keys', () => {
    const sym = Symbol('test')
    const original = {
      [sym]: 'symbol value',
      regular: 'regular value'
    }

    const copy = deepClone(original)

    expect(copy[sym]).toBe('symbol value')
    expect(copy.regular).toBe('regular value')
  })

  test('should handle non-enumerable properties', () => {
    const original = { a: 1, b: 2 }

    // Make 'b' non-enumerable
    Object.defineProperty(original, 'b', {
      value: 2,
      enumerable: false
    })

    const copy = deepClone(original)

    // Both properties should exist
    expect(copy.a).toBe(1)
    expect(copy.b).toBe(2)

    // Check enumeration
    expect(Object.keys(copy)).toEqual(['a'])
    expect(Object.getOwnPropertyNames(copy)).toEqual(['a', 'b'])
  })

  test('should handle nested objects recursively', () => {
    const original = {
      level1: {
        level2: {
          level3: {
            value: 'deep'
          }
        }
      }
    }

    const copy = deepClone(original)

    expect(copy.level1.level2.level3.value).toBe('deep')
    expect(copy.level1).not.toBe(original.level1)
    expect(copy.level1.level2).not.toBe(original.level1.level2)
    expect(copy.level1.level2.level3).not.toBe(original.level1.level2.level3)
  })

  test('should handle arrays within objects', () => {
    const original = {
      arr: [1, { nested: 'obj' }, 3]
    }

    const copy = deepClone(original)

    expect(copy.arr).toEqual([1, { nested: 'obj' }, 3])
    expect(copy.arr).not.toBe(original.arr)
    expect(copy.arr[1]).not.toBe(original.arr[1])
  })

  test('should return primitive values unchanged', () => {
    // deepClone handles primitives, arrays, and plain objects
    // For non-plain objects, it returns the value directly
    expect(deepClone(42)).toBe(42)
    expect(deepClone('string')).toBe('string')
    expect(deepClone(null)).toBe(null)
    expect(deepClone(undefined)).toBe(undefined)
  })

  test('should handle arrays (not through deepCloneObject)', () => {
    const original = [1, { a: 2 }, 3]
    const copy = deepClone(original)

    expect(copy).toEqual([1, { a: 2 }, 3])
    expect(copy).not.toBe(original)
    expect(copy[1]).not.toBe(original[1])
  })

  test('should not clone class instances', () => {
    class TestClass {
      constructor(value) {
        this.value = value
      }
    }

    const instance = new TestClass('test')
    const original = {
      instance: instance,
      regular: { a: 1 }
    }

    const copy = deepClone(original)

    // Class instance should be the same reference (not cloned)
    expect(copy.instance).toBe(instance)
    // Plain object should be cloned
    expect(copy.regular).not.toBe(original.regular)
    expect(copy.regular).toEqual({ a: 1 })
  })

  test('should throw when object has getters/setters', () => {
    const original = {
      _value: 10,
      get value() {
        return this._value
      }
    }

    // This should throw because can't define property with both getter and value
    expect(() => deepClone(original)).toThrow(TypeError)
  })

  test('should not clone objects with custom prototype (returns as-is)', () => {
    const proto = { inherited: 'from proto' }
    const original = Object.create(proto)
    original.own = 'own property'

    // Objects with custom prototype are not plain objects
    // deepClone returns them as-is
    const result = deepClone(original)

    // Should be the same object (not cloned)
    expect(result).toBe(original)
    expect(result.inherited).toBe('from proto')
  })

  test('should handle circular references by creating infinite recursion', () => {
    const original = { a: 1 }
    original.self = original

    // This will cause infinite recursion (stack overflow)
    // We expect it to fail
    expect(() => deepClone(original)).toThrow(RangeError)
  })

  test('should preserve property order', () => {
    const original = {}
    // Add properties in specific order
    original.z = 1
    original.a = 2
    original.m = 3

    const copy = deepClone(original)

    // Properties should be in same order (Reflect.ownKeys preserves order)
    expect(Reflect.ownKeys(copy)).toEqual(['z', 'a', 'm'])
  })

  test('should create objects with Object.prototype, not null prototype', () => {
    const original = Object.create(null)
    original.a = 1
    original.b = 2

    const copy = deepClone(original)

    expect(copy.a).toBe(1)
    expect(copy.b).toBe(2)
    // Creates object with {} which has Object.prototype
    expect(Object.getPrototypeOf(copy)).toBe(Object.prototype)
  })

  test('should preserve writable false from frozen objects', () => {
    const original = { a: 1, b: 2 }
    Object.freeze(original)

    const copy = deepClone(original)

    expect(copy).toEqual({ a: 1, b: 2 })
    // Copy should also be read-only because descriptor.writable is false
    expect(() => { copy.a = 3 }).toThrow()
  })
})

